package edu.pe.cibertec.saibm.inventario.infrastructure.in.rest; import java.net.URI; import java.util.stream.Collectors; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import edu.pe.cibertec.saibm.inventario.domain.exception.InventoryConflictException; @RestControllerAdvice public class InventoryExceptionHandler {@ExceptionHandler(MethodArgumentNotValidException.class)ProblemDetail validation(MethodArgumentNotValidException e,HttpServletRequest r){var p=problem(HttpStatus.BAD_REQUEST,"Invalid request",r);p.setProperty("errors",e.getBindingResult().getFieldErrors().stream().collect(Collectors.toMap(x->x.getField(),x->x.getDefaultMessage(),(a,b)->a)));return p;}@ExceptionHandler(WriteAuthorizationException.class)ProblemDetail forbidden(HttpServletRequest r){return problem(HttpStatus.FORBIDDEN,"Forbidden",r);}@ExceptionHandler(InventoryConflictException.class)ProblemDetail conflict(HttpServletRequest r){return problem(HttpStatus.CONFLICT,"Inventory conflict",r);}@ExceptionHandler(InvalidRequestException.class)ProblemDetail invalid(HttpServletRequest r){return problem(HttpStatus.BAD_REQUEST,"Invalid request",r);}private ProblemDetail problem(HttpStatus s,String t,HttpServletRequest r){var p=ProblemDetail.forStatusAndDetail(s,t);p.setTitle(t);p.setType(URI.create("urn:saibm:inventario:"+s.value()));p.setInstance(URI.create(r.getRequestURI()));return p;}}
